    if 'accountant' in text:
        items.append(['accountants_of',owner])
    if 'consultant' in text:
        items.append(['consultants_of',owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of',owner])
    if 'agent' in text:
        items.append(['agents_of',owner])
    if has_any(text,['lender','finance provider']):
        items.append(['lenders_of',owner])
    if not items and 'representative' in text:
        items.append(['representatives_of',owner])
    return items

def disclosure_condition(text,raw):
    conditions=[]
    if has_any(text,['need to know','need-to-know','strict need to know','bona fide need']):
        conditions.append(['need_to_know',raw])
    if has_any(text,['extent necessary','extent absolutely necessary','reasonably necessary','disclosure is necessary','knowledge of the confidential information is reasonably necessary']):
        conditions.append(['extent_necessary',raw])
    if has_any(text,['written confidentiality agreement','written agreement with','signed the mandatory non-disclosure agreement','signed the mandatory nondisclosure agreement','bound to a duty of confidentiality','bound by obligations of confidentiality','treat the confidential information as confidential','advise such employees','complies with all the provisions of this agreement','obligated to protect']):
        conditions.append(['confidentiality_bound',raw])
    return make_and(conditions)

def operative_information(text):
    return has_any(text,['confidential information','such confidential information','information it receives from','said information','the same'])

def permission_marker(text):
    return has_any(text,['may disclose','may be disclosed','may share','will disclose information','restrict disclosure','restrict access','disclosed only to','except in confidence to','restrictions in paragraph','restrictions under paragraph'])

def prohibition_marker(text):
    return has_any(text,['shall not disclose','not disclose said information','not to disclose','agrees not to','will not provide confidential information','prohibited from disclosing'])

def actor_for(text):
    if 'volunteer' in text:
        return ['named_recipient','Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient','Auditor']
    return ['receiving_party']

def parse_definition(raw,uid,statements):
    text=low(raw)
    if not has_any(text,['representative” means','representatives” means','"representative" means','"representatives" means']):
        return
    items=recipient_items(text,['party'])
    if items:
        add_statement(statements,['define_representative',['party'],make_union(items)],[uid])

def parse_disclosure(raw,support,statements):
    text=low(raw)
    if not operative_information(text):
        return
    actor=actor_for(text)
    if permission_marker(text):
        items=recipient_items(text,['receiving_party'])
        if items:
            permission=['permission',actor,['disclose',['confidential_information'],make_union(items)],disclosure_condition(text,raw)]
            add_statement(statements,permission,support)
    if prohibition_marker(text) and has_any(text,['third party','third parties','any other person','any other organization']):
        exceptions=[]
        if has_any(text,['prior written consent','prior written agreement','prior written approval','expressly authorized in writing']):
            exceptions.append(['authorization_exception','source-stated written authorization'])
        if has_any(text,['required to analyze','required to fulfil','required to fulfill','required in the course of service']):
            exceptions.append(['purpose_exception','source-stated required activity'])
        if exceptions:
            ex=['exception_set',exceptions[0]]
            i=1
            while i<len(exceptions):
                ex=['add_exception',ex,exceptions[i]]
                i+=1
        else:
            ex=['no_exceptions']
        add_statement(statements,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],support)
    if has_any(text,['neither it nor its representatives','neither the receiving party nor its representatives']) and has_any(text,['any other person','any other organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        add_statement(statements,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],['no_exceptions']],support)

def information_scope(text):
    items=[['confidential_information']]
    if has_any(text,['copy','copies','reproduction','record copy','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if has_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def trigger_terms(text):
    triggers=[]
    if has_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        triggers.append(['relationship_nonformation_deadline'])
    if has_any(text,['termination of service','service terminates','service with']):
        triggers.append(['service_termination'])
    if has_any(text,['termination/expiration of the business relation','termination or expiration of the business relation','termination of the business relationship','termination of the working relationship']):
        triggers.append(['relationship_termination'])
    if has_any(text,['termination of this agreement','expiration of this agreement','expiration or termination of this agreement','termination/expiration of this non-disclosure agreement']):
        triggers.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        triggers.append(['purpose_completion'])
    if has_any(text,['upon request','at any time upon request','promptly upon request','request by','request of','request from']):
        triggers.append(['request_by',['disclosing_party']])
    return unique(triggers)

def trigger_value(triggers):
    if not triggers:
        return None
    value=triggers[0]
    i=1
    while i<len(triggers):
        value=['trigger_alternative',value,triggers[i]]
        i+=1
    return value

def has_return_action(text):
    return has_any(text,['shall return','return to','returned to','promptly return','information will be returned'])

def has_destroy_action(text):
    return has_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text

def add_disposal(raw,support,statements):
    text=low(raw)
    triggers=trigger_terms(text)
    if not triggers:
        return
    do_return=has_return_action(text)
    do_destroy=has_destroy_action(text)
    if not do_return and not do_destroy:
        return
    info=information_scope(text)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    add_statement(statements,['disposal_obligation',actor_for(text),action,trigger_value(triggers),['no_exceptions']],support)

def add_retention(raw,uid,statements):
    text=low(raw)
    info=information_scope(text)
    actor=actor_for(text)
    if has_any(text,['entitled to retain','may retain','may maintain a single copy','permitted to retain']):
        add_statement(statements,['retention_permission',actor,info,['after_disposal'],['retention_condition',raw]],[uid])
    if has_any(text,['without retaining any copies','no copies, electronic or otherwise','no copies or records thereof shall be retained','no copy shall be retained']):
        add_statement(statements,['retention_prohibition',actor,info,['after_disposal']],[uid])
    if has_any(text,['not to make or retain copy','shall not retain any copy','must not retain any copy','no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        add_statement(statements,['absolute_retention_prohibition',actor,info],[uid])

def term_has(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def sf_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def sf_add(out,term,support_ids):
    support=sf_unique(support_ids)
    for row in out:
        if isinstance(row,dict) and row.get('term')==term:
            return
    out.append({'term':term,'support_ids':support})

def sf_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def sf_normalize(value):
    if not isinstance(value,str):
        value=str(value)
    text=value.casefold().strip()
    text=text.replace('ofthis','of this')
    text=text.replace('relation- ship','relationship')
    text=text.replace('non-d isclosure','non-disclosure')
    text=text.replace('par-ty','party')
    return text

def sf_actor(text):
    if 'volunteer' in text:
        return ['named_recipient','Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient','Auditor']
    return ['receiving_party']

def sf_information(text):
    items=[['confidential_information']]
    if sf_any(text,['copy','copies','reproduction','record','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if sf_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def sf_triggers(text):
    values=[]
    if sf_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        values.append(['relationship_nonformation_deadline'])
    if sf_any(text,['termination of service','service terminates','termination of the volunteer service']):
        values.append(['service_termination'])
    if sf_any(text,['termination/expiration of the business relationship','termination or expiration of the business relationship','termination of the business relationship','termination of the working relationship']):
        values.append(['relationship_termination'])
    if sf_any(text,['termination of this agreement','expiration of this agreement','expiration or termination of this agreement','termination/expiration of this agreement','termination of the agreement']):
        values.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        values.append(['purpose_completion'])
    if sf_any(text,['upon request','at any time upon request','promptly upon request','request of','request by','request from']):
        values.append(['request_by',['disclosing_party']])
    return sf_unique(values)

def sf_trigger_value(values):
    if not values:
        return None
    value=values[0]
    i=1
    while i<len(values):
        value=['trigger_alternative',value,values[i]]
        i+=1
    return value

def sf_parse_disposal(raw,uid,out):
    text=sf_normalize(raw)
    triggers=sf_triggers(text)
    if not triggers:
        return
    returned=sf_any(text,['shall return','return to','returned to','promptly return','information will be returned'])
    destroyed=sf_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text
    if not returned and not destroyed:
        return
    information=sf_information(text)
    if returned and destroyed:
        action=['action_alternative',['return_to',information,['disclosing_party']],['destroy',information]]
    elif returned:
        action=['return_to',information,['disclosing_party']]
    else:
        action=['destroy',information]
    sf_add(out,['disposal_obligation',sf_actor(text),action,sf_trigger_value(triggers),['no_exceptions']],[uid])

def sf_parse_retention(raw,uid,out):
    text=sf_normalize(raw)
    information=sf_information(text)
    actor=sf_actor(text)
    if sf_any(text,['entitled to retain','may retain','permitted to retain','may maintain a single copy']):
        sf_add(out,['retention_permission',actor,information,['after_disposal'],['retention_condition',raw]],[uid])
    if sf_any(text,['without retaining any copies','without retaining any copy','no copies or records thereof shall be retained','no copy shall be retained','no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        sf_add(out,['retention_prohibition',actor,information,['after_disposal']],[uid])
    if sf_any(text,['not to make or retain copy','shall not retain any copy','must not retain any copy']):
        sf_add(out,['absolute_retention_prohibition',actor,information],[uid])

spec.decision_program:
def subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def has_tag(value,name):
    for item in subterms(value):
        if item[0]==name:
            return True
    return False

def owner_ok(value):
    return isinstance(value,list) and bool(value) and value[0] in ('receiving_party','party','named_recipient')

def class_tags(x,definitions):
    tags=set()
    todo=[x]
    seen=set()
    while todo:
        value=todo.pop()
        if not isinstance(value,list) or not value:
            continue
        name=value[0]
        if name=='representatives_of':
            key=str(value[1]) if len(value)>1 else ''
            if key not in seen:
                seen.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name=='internal_personnel_of' and len(value)>1 and owner_ok(value[1]):
            tags.add('employees_of')
        if name in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of'):
            if len(value)>1 and owner_ok(value[1]):
                tags.add(name)
            continue
        if name=='third_parties':
            tags.add(name)
            continue
        i=1
        while i<len(value):
            if isinstance(value[i],list):
                todo.append(value[i])
            i+=1
    return tags

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=acq_entries(premises)
    if task in ('nda-5','nda-7'):
        return acq_disclosure(task,entries)
    disposal=[]
    retention_permissions=[]
    retention_prohibitions=[]
    absolute_prohibitions=[]
    no_disposal=[]
    no_retention=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0]=='retention_prohibition':
            retention_prohibitions.append(root)
        elif term[0]=='absolute_retention_prohibition':
            absolute_prohibitions.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            no_disposal.append(root)
        elif term[0]=='complete_source_no_retention_effect':
            no_retention.append(root)
    if task=='nda-16':
        endpoint=[]
        relevant=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if not (acq_has(action,'return_to') or acq_has(action,'destroy')):
                continue
            relevant.append(root)
            if acq_has(trigger,'agreement_termination') or acq_has(trigger,'service_termination') or acq_has(trigger,'relationship_termination') or acq_has(trigger,'relationship_nonformation_deadline') or acq_has(trigger,'purpose_completion'):
                endpoint.append(root)
        if endpoint:
            return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(endpoint)}
        if relevant or no_disposal:
            return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+no_disposal)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':acq_unique(retention_prohibitions)}
    if absolute_prohibitions and disposal:
        return {'handled':True,'answer':'Contradiction','used_nodes':acq_unique(absolute_prohibitions+[root for term,root in disposal])}
    relevant=[]
    for term,root in disposal:
        if acq_has(term[2],'return_to') or acq_has(term[2],'destroy'):
            relevant.append(root)
    if relevant or no_retention or no_disposal:
        return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+no_retention+no_disposal)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def disclosure_decision(task,entries):
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='complete_source_no_disclosure_permission':
            absence.append(root)
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose':
            continue
        if not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(root)
        tags=class_tags(action[2],definitions)
        if term[0]=='permission':
            permissions.append((root,tags,action[2]))
        else:
            prohibitions.append((root,tags,action[2]))
    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','independent_contractors_of'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[root]
            if has_tag(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    for root,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def collect_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for node in nodes:
        byid[node.get('id')]=node
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in byid:
                continue
            seen.add(node_id)
            node=byid[node_id]
            for term in subterms(node.get('term')):
                entries.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return entries

def role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='representatives_of':
            key=str(item[1]) if len(item)>1 else ''
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name=='internal_personnel_of' and len(item)>1 and owner_ok(item[1]):
            tags.add('employees_of')
        if name in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of','third_parties'):
            if name=='third_parties' or (len(item)>1 and owner_ok(item[1])):
                tags.add(name)
            continue
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def disclosure_answer(task,entries):
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
        if term[0] in ('complete_source_no_disclosure_permission','complete_source_rule_absence'):
            absence.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(root)
        item=(root,role_tags(action[2],definitions),action[2])
        if term[0]=='permission':
            permissions.append(item)
        else:
            prohibitions.append(item)
    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','independent_contractors_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[root]
            if has_tag(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    for root,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def acq_subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def acq_has(value,name):
    for item in acq_subterms(value):
        if item[0]==name:
            return True
    return False

def acq_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def acq_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    by_id={}
    for node in nodes:
        if isinstance(node,dict):
            by_id[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in by_id:
                continue
            seen.add(node_id)
            node=by_id[node_id]
            for term in acq_subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def acq_role_tags(value,definitions):
