    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','independent_contractors_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','lenders_of'}
    for root,tags,recipient in permissions:
